import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int h = scanner.nextInt();

        int[][] cache = new int[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                cache[i][j] = -1;
            }
        }
        cache[0][0] = 1;

        System.out.println(countStructures(n, h, cache));
    }

    private static int countStructures(int n, int h, int[][] cache) {
        if (cache[n][h] != -1) {
            return cache[n][h];
        }
        if (n == 0) {
            return 0;
        }
        if (h == 0) {
            return countStructures(n, 1, cache);
        }

        int total = 0;
        for (int i = 0; i < n; i++) {
            total += countStructures(n - i - 1, 0, cache) * countStructures(i, h - 1, cache);
            total += countStructures(n - i - 1, h - 1, cache) * countStructures(i, 0, cache);
            total -= countStructures(n - i - 1, h - 1, cache) * countStructures(i, h - 1, cache);
        }
        cache[n][h] = total;
        return total;
    }
}
